    "citizens.hint": { en: "Simulated sign-in. No real identity is used. Pick any demo citizen to post and vote as them.", es: "Inicio de sesi\u00f3n simulado. No se usa ninguna identidad real. Elige cualquier ciudadano demo para publicar y votar como \u00e9l." },
    "citizens.vote": { en: "Sign in to vote \u2014 pick a demo citizen. No sign-in, no vote.", es: "Inicia sesi\u00f3n para votar \u2014 elige un ciudadano demo. Sin inicio de sesi\u00f3n, no hay voto." },
