    "draw.computation.val": { en: "{num} mod {size} = {r} \u2192 +1 = post #{pos}", es: "{num} mod {size} = {r} \u2192 +1 = publicaci\u00f3n n.\u00ba {pos}" },
    "draw.selected": { en: "Selected", es: "Selecci\u00f3n" },
